### NetSuite Connector
```xml
<!-- NetSuite uses SOAP operations — mock like HTTP:WSC -->
<munit-tools:mock-when processor="netsuite:upsert">
  <munit-tools:with-attributes>
    <munit-tools:with-attribute attributeName="config-ref" whereValue="NetSuite_Config"/>
  </munit-tools:with-attributes>
  <munit-tools:then-return>
    <munit-tools:payload value='#[{
      "writeResponse": {
        "status": { "isSuccess": true },
        "baseRef": { "internalId": "NS-001", "type": "salesOrder" }
      }
    }]'/>
  </munit-tools:then-return>
</munit-tools:mock-when>

<!-- NetSuite error: isSuccess=false -->
<munit-tools:then-return>
  <munit-tools:payload value='#[{
    "writeResponse": {
      "status": { "isSuccess": false, "statusDetail": [{ "code": "INSUFFICIENT_PERMISSION", "message": "Not authorized" }] }
    }
  }]'/>
</munit-tools:then-return>
```

